window.VITAMIN_LOCALES["pt"]["calcium"] = { title: "Cálcio", html: "<p class=\"entry-sub\">Mineral estrutural de ossos e dentes — também um player silencioso nas vias muscular, nervosa e de coagulação</p><div class=\"field\"><strong>Nome / formas comuns:</strong> Cálcio (mineral elementar). Os sais complementares comuns incluem carbonato de cálcio, citrato de cálcio, fosfato de cálcio, lactato de cálcio e gluconato de cálcio. O cálcio alimentar chega encadernado em matrizes de laticínios, leites de plantas fortificados, verduras folhosas e peixe ósseo.</div><p>O cálcio é o mineral mais abundante no corpo humano. Quase tudo é armazenado em ossos e dentes; uma pequena fração circulante participa na contração muscular, sinalização nervosa, coagulação sanguínea e liberação de hormônios. O corpo regula firmemente o cálcio do sangue – extraindo do osso quando a dieta é baixa – de modo que “sentir-se bem” nem sempre é a melhor gestão mineral do osso a longo prazo.</p><p>Deus formou nossos quadros com força mineral (imagem do trabalho de ossos e tendões ainda convida a admirar). Stewardship aqui parece padrões de placa ricos em alimentos contendo cálcio, luz solar sensível e vitamina D parceria, movimento de suporte de peso, e humildade sobre megadose comprimidos que não podem substituir um estilo de vida inteiro.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Alimentos lácteos: leite, iogurte, queijo (montantes variam de acordo com o tipo)</li><li>Leites vegetais fortificados, sucos e alguns cereais (verifique etiquetas)</li><li>Sardinhas em conserva ou salmão com ossos comestíveis macios</li><li>Tofu com sais de cálcio (verifique o pacote)</li><li>Verduras em folha, como couves, couves e choy bok (a absorção varia; espinafre é rica em cálcio, mas mais alta em oxalatos que reduzem a disponibilidade)</li><li>Amêndoas, sésamo/tahini, e algumas leguminosas em quantidades contribuintes</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais/históricas</h3><ul><li>Antes da palavra “cálcio” existir na química moderna, culturas de leite premiado, queijo, ossos em brotos, e verdes folhosos para o crescimento e força folclore.</li><li>A era do escorbuto e a ciência da nutrição industrial esclareceram mais tarde os papéis minerais; as histórias de raquitismo e osteomalácia entrelaçaram a vitamina D com o ensino da absorção de cálcio.</li><li>Nenhum versículo da Bíblia nomes “cálcio”; criação enquadramento permanece honesto - ossos e leite pertencem à provisão comum, não um forçado prova-texto.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna</h3><ul><li>A saúde óssea ao longo da vida é o tema central da nutrição: cálcio<strong>adequado com</strong>vitamina D, proteína e atividade – não só cálcio como bala mágica.</li><li>Research explora padrões alimentares (alternativas leiteiras e fortificadas), cálcio suplementar em pessoas que ficam aquém da ingestão de alimentos, e cardiovascular / pedra do rim alerta em torno<strong>alta dose</strong>uso suplementar em alguns contextos.</li><li>A absorção difere pela forma e pela refeição (citrato muitas vezes melhor absorvido com ácido estomacal inferior ao carbonato; carbonato frequentemente tomado com alimentos).</li><li>Qualidade de evidência e recomendações diferem para adultos saudáveis vs. osteoporose diagnosticada sob cuidados médicos -<strong>não auto-tratar doença óssea de um blog.</strong></li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><p>-<strong>A baixa ingestão ao longo do tempo</strong>pode contribuir para a redução do crescimento mineral ósseo ou manutenção quando outros fatores se alinham; quadros graves de deficiência clínica pertencem a clínicos, não a autodiagnóstico. -<strong>Excesso de cálcio suplementar</strong>pode causar constipação, distúrbios digestivos, ou, em altas doses, aumentar a preocupação com pedras renais em pessoas suscetíveis e outros problemas sistêmicos – especialmente quando empilhado com muitos alimentos fortificados mais pílulas.</p><ul><li>Pessoas com hipercalcemia, certos distúrbios paratireoidianos, sarcoidose, ou uma história de cálculos renais de cálcio precisam de orientação clínica antes de suplementos.</li><li>O cálcio pode reduzir a absorção de alguns medicamentos (por exemplo, certos antibióticos, hormona da tiróide)—tempo separado por aconselhamento farmacêutico;<strong>não interrompa medicamentos pré-critos medicamentos.</strong></li><li>Gravidez e lactação aumentam as necessidades – seguir orientação clínica pré-natal, não DIY megadosing.</li></ul></section><section class=\"entry-section\"><h3>Formas complementares</h3><ul><li>Carbonato de cálcio (frequentemente barato; geralmente com refeições)</li><li>Citrato de cálcio (muitas vezes utilizável com ou sem alimentos; útil quando o ácido estomacal é inferior)</li><li>Fórmulas combinadas de suporte ósseo (com vitamina D, magnésio, vitamina K—leia rótulos; mais ingredientes</li><li>Mastigáveis, líquidos e alimentos fortificados como alternativas aos comprimidos grandes</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagemm (não são prescrições)</h3><p>-<strong>Faixas de estilo RDA adulto (Padrões educacionais dostécnicas dos EUA):</strong>com frequência cerca de XXBX 1,000 mg/dia<strong>cálcio elementar para muitos adultos 19–50; cerca de XXBX 1,200 mg/dia</strong>para mulheres 51+ e homens 71+ (alimento + fortificado + suplemento combinado para o total). As tabelas exatas de estágios de vida diferem – verifique os resumos atuais do DRI com um clínico ou nutricionista. -<strong>Níveis superiores</strong>para precaução suplementar existem (geralmente discutido adulto UL em torno de<strong>2,000–2,500 mg/dia</strong>de todas as fontes, dependendo da idade) — alta ingestão empilhada não é “mais bênção.”</p><ul><li>Enfatize<strong>alimento primeiro</strong>; se usando suplementos, calcular cálcio elementar no rótulo, doses divididas (corpo absorve quantidades limitadas de uma vez), e pedir um clínico antes de longo prazo alta dose de uso.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["coenzyme-q10-coq10"] = { title: "Coenzima Q10 (CoQ10)", html: "<p class=\"entry-sub\">X Nutriente auxiliar mitocondrial — cofator antioxidante solúvel em gordura produzido no corpo e encontrado em alimentos</p><div class=\"field\"><strong>Nome/formas comuns: XX HerbXX Coenzima Q10; ubiquinona; ubiquinol (forma reduzida). Vendido em softgels, cápsulas e ocasionalmente líquidos; às vezes emparelhado com gorduras para absorção.\n\nXXB 650 Subtítulo da função-chave:</strong> X Nutriente auxiliar mitocondrial — cofator antioxidante solúvel em gordura produzido no corpo e encontrado em alimentos</div><p>CoQ10 é um composto vitamínico que o corpo sintetiza e também obtém em pequenas quantidades de alimentos. Participa na transferência de energia mitocondrial (transporte de elétrons) e atua como um antioxidante solúvel em gordura em membranas. Níveis podem ser influenciados pela idade, genética, certos medicamentos, e saúde geral -<strong>nenhum dos quais transforma um softgel em uma cura.</strong></p><p>As “poderes” celulares da criação convidam a gratidão sem misticismo. Administração significa etiquetagem honesta, padrões alimentares que apoiam a saúde metabólica e parceria clínica quando medicamentos que afetam as vias do CoQ10 são prescritos –<strong>nunca descontinuar esses medicamentos por conta própria.</strong></p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Carnes de órgãos (coração, fígado) em dietas tradicionais</li><li>Peixe gordo (por exemplo, sardinhas, cavala)</li><li>Carnes musculares em quantidades menores</li><li>Alguns óleos vegetais, nozes e sementes em quantidades modestas</li><li>Alimentos integrais contribuem relativamente pouco em comparação com as doses de miligramas suplementares típicas</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais / históricas</h3><ul><li>CoQ10 foi caracterizado em meados do século XX bioquímica – não uma antiga chamada “herb”.</li><li>Dietas tradicionais que incluíam carnes de órgãos sem saber fornecidas dieta CoQ10 juntamente com outros nutrientes.</li><li>Nenhum sinônimo bíblico; ensine como bioquímica nutricional moderna sob a criação ordenada por Deus.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>Estudado em contextos relacionados à função mitocondrial, desconforto muscular associado à estatina conversas folclore/pesquisa, pesquisa complementar com falha cardíaca sob cuidados médicos e enxaqueca ou temas exploratórios neurológicos – resultados e qualidade do produto variam;<strong>nenhum autoriza tratamento DIY de insuficiência cardíaca ou substituição de cuidados cardiológicos.</strong></li><li>O marketing do ubiquinol vs. ubiquinona é animado; a absorção depende tanto da formulação como das refeições contendo gordura, tanto quanto dos buzzwords.</li><li>Evidence é mista ou condição específica; revisões sistemáticas de qualidade enfatizam cautela contra sobreclamação.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>As verdadeiras síndromes de deficiência primária do CoQ10 são doenças genéticas raras geridas por especialistas – não compras de suplementos casuais. O</li><li>Supplemental CoQ10 é muitas vezes bem tolerado; podem ocorrer distúrbios digestivos ou estimulação semelhante à insónia em pessoas sensíveis.</li><li>Pode interagir com varfarina e anticoagulantes relacionados (alterações INR relatadas em alguns casos) -<strong>coordene com o clínico prescritor; não ajuste os anticoagulantes.</strong></li><li>Os utilizadores de medicamentos para a pressão arterial e diabetes devem informar os clínicos (efeitos aditivos possíveis em teoria).</li><li>Gravidez/amamentação: dados de segurança de rotina insuficientes para utilização de doses elevadas — pergunte antes de completar.</li></ul></section><section class=\"entry-section\"><h3>Forma finas suplementares típicas X TRABALHO Neighbourhood</h3><ul><li>Ubiquinona softimports</li><li>Ubiquinol softgels (frequentemente comercializado para idosos; mais caro)</li><li>Emulsões à base de óleo e cápsulas em pó (difere de absorção)</li><li>Combination “mito support” blendings—escrutinize doses e hype</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagem (não são prescrições)</h3><p>-<strong>No RDA/AI</strong>estabelecido como uma vitamina dietética necessária. A pesquisa complementar</p><ul><li>e os rótulos comerciais muitas vezes caem em faixas adultas brutas de cerca de<strong>100–300 mg/dia</strong>, às vezes divididas; algumas configurações clínicas utilizam valores maiores<strong>sob supervisão</strong>.</li><li>Tome com uma refeição contendo gordura, salvo indicação em contrário do produto.</li><li>Primeiro alimento permanece sábio; suplementos são ferramentas opcionais, não prova de virtude.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["fiber"] = { title: "Fibra", html: "<p class=\"entry-sub\">Carboidratos vegetais indigestíveis — trânsito intestinal, forma de fezes e microbioma aliado de fermentação</p><div class=\"field\"><strong>Nome/formas comuns:</strong> Fibra dietética — solúvel (por exemplo, beta-glucanos, pectinas, algumas gengivas, psilium) e insolúvel (por exemplo, celulose, muitas partículas de farelo de trigo). Formas suplementares incluem casca de psilium, metilcelulose, inulina/FOS, dextrina de trigo e fibras vegetais mistas.</div><p>Fibra é a porção de alimentos vegetais não totalmente digeridos por enzimas humanas. Fibras solúveis podem formar géis e são fermentados por micróbios intestinais a ácidos graxos de cadeia curta; fibras insolúveis adicionam volume e ajudam o movimento das fezes. Ambos pertencem a um padrão variado de plantas - feijão, grãos integrais, frutas, legumes, nozes e sementes.</p><p>O jardim e o campo (vocação Gênesis para cultivar) ainda nos alimentam com cascas, peles e paredes celulares que não podemos quebrar totalmente – mas nossos vizinhos microbianos podem. Essa parceria é providência, não uma tendência. Stewardship significa aumentar gradualmente a fibra com água, não punir o intestino durante a noite com pós megadose.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Legume: feijão, lentilhas, grão de bico, ervilhas divididas</li><li>Grãos inteiros: aveia, cevada, arroz integral, trigo integral, quinoa</li><li>Frutos: bagas, maçãs/peras com pele, citrinos, ameixas</li><li>Vegetais: blinhas, cenouras, greens folhosos, alcachofras</li><li>Nuts, seeds, and abacates</li><li>Psyllium and other fiber suplements when food fail short (with clinican/dietitian sense)</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais / históricas</h3><ul><li>Dietas tradicionais ricas em grãos inteiros, pulsoeração e legumes fornecidos fibra muito antes da palavra ser cunhada. A ciência da nutrição do século XX da</li><li>associou dietas refinadas à constipação e discussões mais amplas sobre o padrão crônico-doença.</li><li>A vida agrícola bíblica assumiu pães com farelo e produtos de jardim – ensinar gratidão, não anacrônica “versículos de fibra”.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>Fibra adequada regular está associada em pesquisas populacionais e clínicas de nutrição com fezes mais regulares, padrões de colesterol melhorados para algumas fibras viscosas (por exemplo, aveia, psilium), respostas pós-alimentares de glicose em muitos contextos, e suporte saciedade. A fermentação do microbioma</li><li>de certas fibras é um campo de pesquisa ativo, prometedor e não mágico “detox”.</li><li>Nem todas as fibras agem da mesma forma; combinam a ferramenta (por exemplo, psilium para forma de fezes vs. inulina que pode gasear mais) com o objetivo educacional e tolerância.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>Padrões de baixa fibra comumente contribuem para a constipação para muitas pessoas — ainda descartar causas médicas com um clínico quando os sintomas são novos, graves ou acompanhados de sangue, perda de peso ou dor.</li></ul><p>-<strong>Grandes aumentos súbitos</strong>causam gás, inchaço e cãibras—atite lentamente e beba um líquido adequado.</p><ul><li>Suplementos de fibra pode reduzir a absorção de alguns medicamentos, se tomado simultaneamente – tempo separado.</li><li>Pessoas com distúrbios da deglutição, estenoses ou certas cirurgias GI precisam de aconselhamento individualizado antes da fibra de massa.</li><li>dietas restritas de baixa fibra são às vezes prescritos medicamente (por exemplo, flares agudos de doenças intestinais específicas) —<strong>seguir o clínico, não um slogan de bem-estar.</strong></li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>Psyllium hush pó ou cápsulas</li><li>Metilcelulose e outras fibras semi-sintéticas</li><li>Inulin, FOS, GOS (prebiótico-leaning; gassier para alguns)</li><li>Parcially hidrolyzed guar gum and mixed blends</li><li>Food concentrates (bran brean cereals)—watch such and portion</li></ul></section><section class=\"entry-section\"><h3>Faixas educadoras de dosem (não são prescrições)</h3><p>-<strong>Metas no estilo AI para adultos (padrões educacionais dos EUA):</strong>aproximadamente<strong>~25 g/dia</strong>para muitas mulheres adultas e<strong>~38 g/dia</strong>para muitos homens adultos (muitas vezes enquadrado como cerca de<strong>14 g por 1.000 kcal</strong>) — as necessidades individuais variam.</p><ul><li>etiquetas de psilium suplementar muitas vezes sugerem colheres de chá misturadas em copos cheios de água; começar baixo.</li><li>Crianças, gravidez e condições médicas do GI precisam de alvos personalizados – pergunte a um profissional.</li><li>Prefere placas sobre pós quando possível.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["glucosamine-and-chondroitin"] = { title: "Glucosamina e condroitina", html: "<p class=\"entry-sub\">Suplementos de bloco de construção de cartilagens – parceiros de pesquisa de conforto conjunto (pílulas de crescimento não milagrosas)</p><div class=\"field\"><strong>Nome / forma comuns:</strong> Glucosamina (frequentemente sulfato de glucosamina ou cloridrato; às vezes de quitina de marisco, às vezes fontes fermentadas vegetarianas) e sulfato de condroitina (muitas vezes de cartilagem bovina, suína ou marinha). Vendido separadamente ou combinado; ocasionalmente com HSH ou misturas de articulações botânicas.</div><p>Glucosamina é um aminoaçúcar utilizado no corpo como bloco de construção para glicosaminoglicanos na cartilagem e outros tecidos conjuntivos. O sulfato de condroitina é um importante componente glicosaminoglicano da cartilagem que atrai água e contribui para a resiliência. Formas suplementares visam fornecer esses compostos oralmente - a absorção e utilidade clínica permanecem debatidas e dependentes do produto.</p><p>Ossos e articulações nos levam através da vocação e adoração; cuidar deles inclui peso saudável, força muscular, movimento, e cuidados médicos quando necessário. Suplementos podem ser discutidos como adjuvantes – não substitutos para avaliação de dor, lesão ou artrite inflamatória.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Caldos ósseos e cortes cartilaginosos fornecem compostos relacionados tradicionalmente, mas quantidades são variáveis e não equivalentes a doses padronizadas de suplemento</li><li>Conchas de mariscos são fontes industriais para muitos produtos de glucosamina – alimentos não típicos de chapa</li><li>Não existe uma rica fonte de produção diária que combine com as doses de miligrama de cápsula</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais/históricas</h3><ul><li>Culinária tradicional valorizada “nariz a rabo” para comer (pele, tendões, caldos) para o folclore de força.</li><li>Modernos suplementos de glucosamina/condroitina aumentaram no final do século XX joint-health marketing e pesquisa.</li><li>Não nutracêuticos bíblicos pelo nome — manter a criação enquadrando geral (mordomia corpo).</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>Ensaios em seres humanos e revisões sobre alívio de sintomas de osteoartrite mostram<strong>resultados</strong>mistos: algumas pessoas e algumas preparações relatam modestos benefícios de conforto ou função; outras mostram pouca diferença em relação ao placebo. As Diretrizes</li><li>variam de acordo com o país e a organização; muitos clínicos consideram um estudo com tempo limitado opcional para osteoartrite leve após discutir as expectativas.</li><li>Qualidade, dose, sulfato vs. sais de HCl e produtos combinados diferem – a heterogeneidade complica os títulos.</li></ul><p>-<strong>Não</strong>estabelecido para reverter a destruição articular ou substituir a cirurgia indicada, a fisioterapia ou o tratamento modificador da doença para a artrite autoimune.</p></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>Não clássico “vitaminas deficiência”; baixa ingestão alimentar não é diagnosticada como escorbuto.</li><li>Geralmente bem tolerado; desconforto digestivo leve possível.</li></ul><p>-<strong>Alergia a mariscos:</strong>muitos produtos de glucosamina derivam de mariscos — escolha fontes vegetarianas certificadas se alérgicas e verificar rotulagem.</p><ul><li>Chondroitin pode ter interações teóricas anticoagulantes - cuidado com varfarina e risco de hemorragia;<strong>pergunte ao clínico; nunca altere os anticoagulantes.</strong></li><li>Diabetes: a glucosamina tem levantado historicamente preocupações teóricas de glicose; dados modernos são matizes — monitor com clínico se relevante.</li><li>Gravidez/ aleitamento: dados insuficientes para utilização de doses elevadas de rotina – evitem, a menos que sejam aconselhados.</li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>Glucosamine sulfato cápsulas (comuns em produtos de estilo europeu)</li><li>Glucosamine HCl</li><li>Chondroitin sulfato isolado ou 2-em-1 fórmulas</li><li>Produtos de articulações veterinárias são<strong>não</strong>doseados para seres humanos – não mastigue animais de estimação como medicamento para pessoas</li></ul></section><section class=\"entry-section\"><h3>Faixas educadoras de dosagem (não são prescrições)</h3><p>-<strong>X No RDA.</strong></p><ul><li>Os estádios de adultos estudados agrupam-se frequentemente perto de<strong>~1,500 mg/dia de glucosamina</strong>e<strong>~800–1,200 mg/dia de condroitina</strong>, por vezes divididas em doses – as etiquetas dos produtos variam. A prática educacional</li><li>muitas vezes sugere reavaliar após várias semanas a alguns meses com um clínico se usado para o conforto da osteoartrite – parar se nenhum benefício significativo ou se os efeitos adversos aparecem.</li><li>Mantenha as expectativas modestas; prosseguir o diagnóstico para inchaço articular, articulações bloqueadas, ou artrite febril.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["iron"] = { title: "Ferro", html: "<p class=\"entry-sub\">Mineral portador de oxigênio de hemoglobina – parceiro de metabolismo energético que exige respeito tanto pela falta quanto pela sobrecarga</p><div class=\"field\"><strong>Nome / formas comuns:</strong> Ferro como heme ferro (de carne animal) e ferro não heme (plantas e alimentos fortificados). Os sais complementares incluem sulfato ferroso, gluconato ferroso, fumarato ferroso, ferro polissacarídeo e várias formas de liberação suave ou lenta; ferro intravenoso é<strong>prescrição apenas cuidados médicos</strong>.</div><p>O ferro é essencial para a hemoglobina e a mioglobina (transporte de oxigênio), e para enzimas do metabolismo energético e da síntese de DNA. O corpo recicla o ferro com cuidado e absorve mais quando as reservas estão baixas — mas tem vias limitadas de excreção, de modo que o excesso pode acumular-se perigosamente.</p><p>A vida do sangue (a solenidade de Levítico sobre o sangue) lembra-nos que a entrega de oxigênio é um depósito sagrado, não um slogan de academia. Deficiência e sobrecarga de ferro são condições <strong>diagnosticadas em laboratório</strong>. Adivinhar com comprimidos de alta dose pode prejudicar.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li><strong>Heme:</strong> carne bovina, cordeiro, vísceras, carne escura de aves, alguns peixes/mariscos</li><li><strong>Não heme:</strong> lentilhas, feijões, tofu, sementes de abóbora, castanhas de caju, espinafre e outros vegetais, melaço, cereais e pães fortificados com ferro</li><li><strong>Ajudas de absorção (educativas):</strong> alimentos ricos em vitamina C com refeições de ferro não heme; evite tomar chá/café ou grandes doses de cálcio no mesmo momento exato se a absorção for uma preocupação clínica</li><li>Panelas de ferro fundido podem adicionar pequenas quantidades a alimentos ácidos</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais / históricas</h3><ul><li>Curandeiros antigos associavam fraqueza e aparência pálida à falta dietética muito antes dos testes de ferritina.</li><li>A “doença verde” e, depois, histórias de clorose em jovens mulheres cruzam insegurança alimentar e narrativas de perda de sangue.</li><li>Dietas agrárias bíblicas incluíam carnes e verduras sem nomear o ferro elemental — ensine provisão, não anacronismo químico.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>A anemia por deficiência de ferro continua sendo uma grande questão nutricional global — triagem e tratamento pertencem aos clínicos.</li><li>A pesquisa distingue deficiência absoluta, deficiência funcional e anemia de doença crônica — abordagens diferentes.</li><li>Programas de fortificação e suplementação direcionada são ferramentas de saúde pública; megadosagem individual sem laboratórios é imprudente.</li><li>Os contextos atléticos, menstruais, de gravidez e sangramento GI mudam o risco – questões de cuidado personalizadas.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><p>-<strong>Sintomas de deficiência</strong>(fadiga, palidez, pernas inquietas, etc.) sobrepõem-se a muitas condições— teste<strong>, não adivinhe.</strong> -<strong>Excesso / sobrecarga:</strong>overdose pediátrica acidental de comprimidos de ferro é uma emergência clássica de envenenamento; hemocromatose e repetidos suplementos desnecessários podem danificar órgãos.</p><ul><li>Sais ferrosos geralmente causam náuseas, obstipação ou diarreia, e fezes escuras; tomar como indicado para reduzir o problema de estômago.</li><li>Ferro reduz a absorção de alguns medicamentos (levotiroxina, certos antibióticos)—tempo separado;<strong>não parar esses medicamentos.</strong></li><li>Homens, mulheres pós-menopáusicas e pessoas com genética ferro-sobrecarga geralmente devem<strong>não</strong>tomar ferro rotineiramente sem indicação.</li><li>Gravidez precisa de aumento — use orientação pré-natal, não navegação farmácia de alta dose aleatória.</li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>Sulfato ferroso (comum, eficaz, mais efeitos colaterais GI para alguns)</li><li>Gluconato ferroso / fumarato</li><li>Complexos de ferro polissacárido e ferro carbonílico (comercialização varia)</li><li>Gotas líquidas para pediatria —**</li><li>Ferro IV: clínica apenas</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagem (não são prescrições)</h3><p>-<strong>Adulto RDA-estilo (Padrões educacionais U.S.):</strong>sobre<strong>8 mg/dia</strong>X para homens adultos e mulheres pós-menopausa; cerca de<strong>XX</strong>/dia<strong>para muitas mulheres pré-menopausas; cerca de</strong><strong>/dia</strong>/dia XXBX na gravidez – alimentos + pré-natal, conforme indicado. As doses de tratamento</p><ul><li>para deficiência diagnosticada são frequentemente<strong>mais elevadas</strong>e limitada pelo tempo –<strong>apenas com orientação clínica</strong>(existem frequentemente esquemas de ferro elementar discutidos em referências médicas; não são modelos DIY aqui).</li><li>Adulto suplemento UL comumente discutido perto<strong>45 mg/dia</strong>ferro elementar de suplementos/fortificantes a menos que um clínico prescreve mais para o tratamento.</li><li>Enfatize laboratórios (CBC, ferritina, etc.) antes e durante o uso terapêutico.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["magnesium"] = { title: "Magnésio", html: "<p class=\"entry-sub\">Cofactor mineral de centenas de reações enzimáticas — músculo, nervo, ritmo e metabolismo energético parceiro</p><div class=\"field\"><strong>Nome/formas comuns:</strong> Magnésio (mineral essencial). Formas complementares incluem citrato de magnésio, glicinato (bisglicinato), óxido, cloreto, malato, sulfato (Epsom - uso frequente de banho), e outros. O “magnésio elementar” nos rótulos é mais importante do que o peso dos comprimidos.</div><p>O magnésio participa da química de energia ATP, relaxamento muscular/balanço de contração, transmissão nervosa, manipulação de glicose sanguínea e matriz mineral óssea. Grande parte do magnésio do corpo senta-se no osso e tecido mole; os níveis sanguíneos podem permanecer enganosamente normais, enquanto o estado corporal total é subótima—interpretação precisa de contexto clínico.</p><p>Os minerais silenciosos da criação impedem os nervos e os músculos do caos. Stewardship parece legumes verdes, legumes, nozes e grãos inteiros – e cuidado com sais de dose laxante vendidos como milagres “calmo”.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Produtos hortícolas de folha (plantas centradas em clorofilas)</li><li>Frutos de casca rija</li><li>Leguminosas e grãos inteiros</li><li>Chocolate escuro / cacau em montantes contribuintes</li><li>Algumas águas minerais</li><li>Arro lares de arrematados e de arrematados</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais / históricas</h3><ul><li>Sal de Epsom (sulfato de magnésio) banhos e folclore folclórico folclórico externo são séculos de idade, prova de cura sistêmica.</li><li>O reconhecimento moderno de FBI cresceu com dietas alimentares refinadas e perdas relacionadas ao GI/álcool.</li><li>Nenhum versículo mineral da Bíblia forçado necessário; ervas verdes do campo permanecem linguagem de gratidão justa.42</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>Os temas de pesquisa incluem os adjuvantes de prevenção da enxaqueca em alguns protocolos, folclore de conforto do sono/músculo com evidências mistas por forma e dose, sinergia padrão de pressão arterial (por exemplo, dieta rica em magnésio tipo DASH), e correção de baixos níveis em estados de deficiência.</li><li>Diferentes sais têm biodisponibilidade e potência laxante diferentes (óxido muitas vezes mais barato e mais catártico; glicinato/citrato muitas vezes preferido para tolerância em comparações educacionais).</li><li>Só o botas de magnésio é um marcador de status imperfeito – os clínicos integram história, medicamentos e, às vezes, outros testes.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>O baixo risco de magnésio aumenta com perdas de GI, distúrbio do uso de álcool, certos diuréticos, diabetes descontrolada e má ingestão – avaliem clinicamente.</li></ul><p>-<strong>O excesso suplementar</strong>geralmente causa diarreia, cãibras e náuseas; ingestão extrema pode causar toxicidade cardíaca/neurológica perigosa, especialmente se os rins estão prejudicados. -<strong>Doença renal:</strong>não auto-suplemento magnésio sem orientação nefrológica.</p><ul><li>Interacções possíveis com alguns antibióticos e bifosfonatos (diminuição); precaução com medicamentos neuromusculares – verificação farmacológica.</li><li>“Calm gummies” mais pós de óxido mais laxantes pode empilhar involuntariamente.</li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>Magnésio glicinato / bisglicinato (frequentemente mais suave no intestino)</li><li>Citrato de magnésio (boa absorção; pode afrouxar fezes)</li><li>Óxido de magnésio (elementar% elevado mas menor absorção; uso laLVÁTICO comum)</li><li>Loções temáticas e banhos de Epsom (variável de absorção sistêmica/incerte—não assume banho igual a repleção oral)</li><li>Multivitaminas com modestas quantidades de magnésio</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagemm (não são prescrições)</h3><p>-<strong>Adulto RDA-estilo (U.S.):</strong>XXX<strong>X/dia</strong>para muitas mulheres adultas e<strong>XX</strong>X/dia**/dia para muitos homens adultos (alimentação + suplementos para o total).</p><ul><li>Suplemento<strong>UL para o magnésio farmacológico</strong>comumente discutido perto<strong>350 mg/dia elementar de suplementos apenas</strong>(o magnésio alimentar não contada da mesma forma no enquadramento UL)—porque diarreia e outros efeitos aparecem com excesso suplementar. A repetição da deficiência de</li><li>pode utilizar diferentes regimes supervisionados.</li><li>Prefere padrões alimentares; use suplementos para preencher lacunas sob orientação quando necessário.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["melatonin"] = { title: "Melatonina", html: "<p class=\"entry-sub\">Hormônio da escuridão do relógio circadiano — mensageiro para dormir (não um martelo sedativo)</p><div class=\"field\"><strong>Nome / formas comuns:</strong> Melatonina (N-acetil-5-metoxitriptamina). Vendido em comprimidos, cápsulas, líquidos, gomas e formas sublinguais; de libertação imediata e prolongada. Ocorre naturalmente em pequenas quantidades em alguns alimentos; o corpo sintetiza-a da serotonina na glândula pineal.</div><p>A melatonina é um hormônio que ajuda a sinalizar a noite biológica aos relógios do corpo. A luz à noite suprime-a; a escuridão permite a ascensão. A melatonina suplementar fornece uma dose exógena muito acima dos níveis típicos de sangue noturno da secreção pineal – útil como uma ferramenta de tempo para algumas pessoas, usada demais como um doce noturno para outras.</p><p>“Deus fez as duas grandes luzes” e fixou tempos e estações (Gênesis 1; noite ordenada do Salmo 104). Honrar o sono inclui noites escuras, horários consistentes e cuidados médicos para insônia – megadoses de goma não ilimitadas para crianças sem conselhos.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Traços em algumas frutas (por exemplo, cerejas, uvas), nozes e alimentos fermentados — interessando bioquimicamente, raramente igual a miligramas de suplementos</li><li>Proteínas dietéticas contendo triptofano suportam indiretamente as vias serotonina/melatonina como parte da dieta global – não uma “dose” precisa</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais / históricas</h3><ul><li>A melatonina foi identificada em meados do século XX; o folclore pineal é mais antigo do que o nome da molécula.</li><li>As culturas pré-elétricas experimentaram sinais de noite escura mais fortes – a higiene moderna da luz está recuperando parcialmente esse padrão.</li><li>Panorama não é um remédio bíblico chamado; sabedoria circadiana se encaixa na linguagem da ordem da criação sem inventar versos.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>Usos educacionais mais bem suportados muitas vezes se relacionam com<strong>alinhamento circadiano</strong>: jet lag, padrões de fase de sono atrasado, e alguns contextos de trabalho em turnos - resultados variam.</li><li>A evidência de insônia primária crônica é mista; abordagens de terapia do sono (CBT-I) muitas vezes ultrapassam o aumento infinito de miligramas.</li><li>O uso de crianças e adolescentes é comum na cultura, mas precisa de supervisão clínica – as fórmulas e a pureza variam.</li><li>Liberação prolongada vs. libertação imediata servem diferentes teorias de tempo.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>Não enquadrado como deficiência de vitamina C; baixa melatonina noturna pode refletir exposição à luz, idade, ou horários de mudança.</li><li>Os efeitos secundários podem incluir sonolência no dia seguinte, sonhos/noites vívidos, dores de cabeça ou alterações de humor em pessoas sensíveis.</li><li>Pode afetar a pressão arterial, glicose ou limiares convulsivos em alguns contextos – pergunte se for relevante.</li><li>Preocupações teóricas imunológicas e hormonais aparecem em discussões especiais (por exemplo, alguns contextos auto-imunes ou reprodutivos) — julgamento clínico.</li><li>O controle de qualidade dos suplementos varia; alguns produtos têm contido mais ou menos do que rotulado em pesquisas publicadas historicamente.</li></ul><p>-<strong>Não combinar casualmente com outros sedativos ou álcool.</strong></p><ul><li>Gravidez/ aleitamento: pergunte antes de utilizar.</li><li>Nunca substitua a avaliação da apnéia do sono, depressão ou insónia relacionada com a dor por melatonina isoladamente.</li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>Comprimidos de dose baixa (0.5–1 mg conversas educativas iniciais)</li><li>Retalho comum 3–5 mg (muitas vezes mais do que a necessidade fisiológica de cronometragem)</li><li>Formulações de libertação prolongada</li><li>Líquidos/ chicletes pediátricos —<strong>X apenas com orientação pediátrica</strong></li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagem (não são prescrições)</h3><p>-<strong>No RDA.</strong></p><ul><li>Pesquisa circadiana e educação clínica frequentemente enfatizam que<strong>doses mais baixas</strong>(por vezes<strong>0.5–3 mg</strong>) tomadas em um tempo de relógio adequado pode ser suficiente para metas de tempo; doses mais elevadas de varejo não são automaticamente melhores. Os protocolos</li><li>Jet-lag variam de acordo com a direção de viagem—brief, uso proposital difere de meses de escalada noturna.</li><li>Se os problemas de sono persistirem além de ensaios curtos, procure cuidados médicos/comportamentais do sono em vez de empilhar miligramas.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["omega-3-fatty-acids-fish-oil-ala"] = { title: "Ácidos gordos Ómega-3 (Óleo de Peixe / ALA)", html: "<p class=\"entry-sub\">Família de gordura essencial — temas de pesquisa de fluidez, sinalização e nutrição de triglicerídeos</p><div class=\"field\"><strong>Nome / formas comuns:</strong> Ómega-3 ácidos graxos poliinsaturados – especialmente EPA (ácido eicosapentaenóico) e DHA (ácido docosahexaenóico) de fontes marinhas; ALA (ácido alfa-linolênico) de plantas. As formas incluem softgels de óleo de peixe, concentrados de triglicérides vs. éster etílico, óleo de krill fosfolipídio, óleo de algas (vegan DHA/EPA) e alimentos de linho/chia/walnut para ALA.</div><p>Omega-3s são gorduras essenciais que o corpo não pode fazer do zero em quantidades necessárias. ALA de plantas converte apenas<strong>limitada</strong>para EPA/DHA em humanos; direto EPA/DHA de frutos do mar ou óleo de algas aumenta mais de forma confiável os níveis de cadeia longa. Incorporam em membranas celulares e influenciam a sinalização eicosanóide relacionada ao tom de inflamação — modulação<strong>, não uma licença para reivindicar doenças inflamatórias.</strong></p><p>Os mares repletos de vida (imagem Salm das águas) e plantas com sementes oferecem gorduras. A gestão inclui pesca sustentável, etiquetas honestas (EPA+DHA miligramas – não apenas “óleo de peixe 1,000 mg”), e supervisão médica para regimes de altas doses.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><p>-<strong>EPA/DHA:</strong>salmão, sardinha, cavala, arenque, anchovas, truta; óleo de peixe; óleo de algas -<strong>ALA:</strong>linhaça e óleo de linho, sementes de chia, nozes, sementes de cânhamo, óleo de canola, alguns greens folhosos em pequenas quantidades</p><ul><li>ovos ou leites fortificados (verifique etiquetas)</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais/históricas</h3><ul><li>Povos costeiros e ribeirinhos prezados peixes oleosos; culturas interiores apoiadas em sementes e animais com diferentes perfis de gordura.</li><li>Óleo de fígado tradições entrelaçado vitaminas A/D com ômega-3s – dose cuidadosamente; excesso de vitamina A é real.</li><li>Culturas bíblicas que comem peixes (narrativas do Mar da Galiléia) apoiam a gratidão pelo peixe como alimento – não um ensaio moderno da EPA.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>Strongest estabeleceu o uso médico de<strong>prescrição de alta dose ômega-3</strong>refere-se a<strong>triglicerídeos altos</strong>sob cuidados clínicos - diferente de softgels farmácia.</li><li>Achados gerais de saúde cardíaca para EPA/DHA suplementar de baixa a moderada são misturados em épocas de ensaios; padrões de peixes alimentares permanecem amplamente encorajados nas diretrizes alimentares.</li><li>Cérebro, olho (DHA), gravidez/vida precoce DHA, e temas de pesquisa de humor existem com certeza variável - evitar reivindicações absolutas.</li><li>ALA suporta o estado de gordura essencial; não é um substituto completo para EPA/DHA se esses são especificamente desejados.</li></ul></section><section class=\"entry-section\"><h3>As precauções por deficiência / excesso</h3><ul><li>Frank deficiência de ácido essencial gordo é incomum em dietas modernas variadas, mas possível em ingestão altamente restrita ou de má absorção grave.</li><li>Óleo de peixe pode causar arrotos, indigestão, ou fezes soltas.</li><li>Ingestão mais elevada pode aumentar a tendência de sangramento – especialmente com anticoagulantes/antiplaquetários ou antes da cirurgia – informar os clínicos<strong>; não interrompa medicamentos pré-critos anticoagulantes.</strong></li><li>Altas doses moduladoras imunitárias necessitam de contexto médico.</li><li>Cuidado contaminante historicamente para alguns peixes (mercúrio)—prefere espécies de baixo mercúrio e óleos purificados de marcas respeitáveis; a gravidez segue orientações de orientação de peixes.</li><li>Óleos rançosos cheiram/gostem fora — guarde fresco e escuro.</li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>Standard Fish Oil softgels (leia<strong>EPA e DHA</strong>linhas)</li><li>Produtos de prescrição EPA ou EPA+DHA concentrados (médicos)</li><li>Óleo de algas para vegetarianos/vegans</li><li>Óleo de linho para ALA (refrigerato; não óleo de fritura)</li><li>Óleo de fígado de bacalhau (representa também vitaminas A e D)</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagemm (não são prescrições)</h3><p>-<strong>ALA-style (EUA):</strong>cerca de<strong>1.1 g/dia</strong>para muitas mulheres adultas e<strong>1.6 g/dia</strong>para muitos homens adultos. -<strong>EPA+DHA:</strong>nenhum RDA clássico único; muitas discussões educacionais coração-saúde alimentos terra perto<strong>~250–500 mg/dia combinado EPA+DHA</strong>de peixes/alimentos para adultos em geral – maiores metas terapêuticas existem<strong>apenas sob supervisão médica</strong>(por exemplo, regimes multi-gramas para triglicérides).</p><ul><li>Gravidez: seguir orientações obstétricas sobre peixes e DHA; os produtos pré-natais variam.</li><li>O peixe alimentar duas vezes por semana é um padrão de orientação comum quando apropriado e de baixo mercúrio.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["probiotics"] = { title: "Probióticos", html: "<div class=\"field\"><strong>Nome/formas comuns:</strong> Microorganismos vivos que, quando administrados em quantidades adequadas, podem conferir um benefício à saúde do hospedeiro (definição do tipo FAO/WHO utilizada educacionalmente). Gêneros comuns: <em>Lactobacillus</em>, <em>Lacticaseibacillus</em>, <em>Bifidobacterium</em>, <em>Saccharomyces boulardii</em> (uma levedura benéfica), e outros. As formas incluem cápsulas, pós, alimentos fermentados (iogurte com culturas vivas, kefir, kimchi, chucrute, miso) e alguns produtos fortificados.\n\nmontante<strong>Subtítulo da função-chave:</strong>Microbos úteis de ecologia alimentar e intestinal — hóspedes específicos de estirpes, não um “botão de restauração” universal</div><p>Os probióticos são selecionados micróbios vivos estudados para efeitos intestinos e imunes adjacentes. São<strong>não</strong>o mesmo que prebióticos (fibras que alimentam micróbios) ou todo o microbioma. Benefícios — quando presentes — são frequentemente<strong>deformação específica e resultado específico</strong>. Os micróbios mortos e os alimentos fermentados sem contagens ao vivo garantidas estão relacionados, mas conversas distintas.</p><p>Somos mordomos de uma ecologia interior que não inventamos. Humildade significa escolher cepas alinhadas a evidências para objetivos definidos, praticar a segurança alimentar em fermentos domésticos,medicar cuidados para diarreia com sangue, febre alta, ou doença grave em vez de “mais UFCs”.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Iogurte e kefir rotulados com culturas activas vivas</li><li>Legumes fermentados tradicionais (sauerkraut, kimchi) que não são pasteurizados/refrigerados quando micróbios vivos são desejados</li><li>Miso, tempeh e algumas bebidas fermentadas tradicionais (contagens de vida variáveis)</li><li>Nota: pic lanches de salmouras de vinagre e produtos pasteurizados estanques podem não ter probióticos vivos</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais / históricas</h3><ul><li>Leite fermentado e vegetais aparecem em culturas como sabedoria de preservação.</li><li>Metchnikoff-era longevidade folclore popularizado micróbios lácticos; ciência de tensão moderna é muito mais preciso.</li><li>Biblical laticínios e alimentos de jardim podem ser apreciados sem alegar antigos israelitas engoliu CFU-contadas cápsulas.</li></ul></section><section class=\"entry-section\"><h3>Temas algemas modernas (qual Moldávia)</h3><ul><li>Certas cepas têm evidências em cenários específicos: redução do risco de diarreia associada a antibióticos, alguns contextos de diarreia infecciosa, cuidados especiais com bolsites e pesquisa de sintomas selecionados IBS —<strong>combinam com a indicação; garrafas de hype raramente revelam isso bem.</strong></li><li>“Saúde da gut”, peso, humor e marketing da pele muitas vezes ultrapassam evidências robustas.</li><li>Sobrevivência através de ácido estomacal, dose (UFC) e estabilidade da prateleira são tão importantes quanto a palavra “probiótico” do rótulo frontal. Os postbióticos</li><li>e os anaeróbios da próxima geração são pesquisas emergentes — ainda não são mágicas.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>Não é um modelo clássico de deficiência de vitaminas.</li><li>Geralmente seguro para muitas pessoas saudáveis; gás ou inchaço pode ocorrer inicialmente.</li></ul><p>-<strong>Foram notificadas infecções invasivas raras de organismos probióticos – apenas supervisão médica</strong>, doentes gravemente doentes ou de linha central.**</p><ul><li>Precaução com <em>Saccharomyces boulardii</em> em contextos de cateteres centrais e alergia a leveduras.</li><li>Pancreatite grave e algumas configurações hospitalares historicamente levantaram preocupações para produtos específicos — siga orientação institucional.</li><li>Falhas de fermento doméstico podem crescer micróbios prejudiciais — assuntos de animação.</li><li>Não utilize probióticos para atrasar o tratamento com disenteria, C. diff sem planos médicos ou doença infantil.</li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>Cápsulas multiestirpe refrigeradas</li><li>Formantes de esporos estáveis em prateleiras (biologia diferente—leia evidências para esse esporo) pacotes</li><li><em>S. boulardii</em></li><li>Produtos sinbióticos (probióticos + fibras prebióticas)—assiste FODMAP sensibilidade</li><li>Alimentos-primeiro iogurte/cefir padrões</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagem (não são prescrições)</h3><p>-<strong>Sem exigência universal RDA/UFU.</strong></p><ul><li>As doses adultas estudadas variam frequentemente entre cerca de<strong>1-10+ bilhões de UFC/dia</strong>dependendo da tensão e resultado; alguns protocolos usam quantidades mais elevadas a curto prazo – o rótulo<strong>e os números genéricos do clínico.</strong></li><li>Para o uso educacional da era antibiótica, separar o momento da dose de antibiótico quando aconselhado, e continuar apenas como indicado.</li><li>Escolha produtos listando gênero, espécie, estirpe ID, UFC no final do prazo de validade e condições de armazenamento.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["vitamin-b12-cobalamin"] = { title: "Vitamina B12 (Cobalamina)", html: "<p class=\"entry-sub\">Nerve-sheath &amp; blood-forming vitamin — methylation cofactor that vegetarians and older adults should take serious</p><div class=\"field\"><strong>Nome / formas comuns:</strong> Vitamina B12; cobalamina. Formas suplementares incluem cianocobalamina, metilcobalamina, adenosilcobalamina e hidroxocobalamina (a última também utilizada como injeções medicamente). Encontrado em alimentos de origem animal e alimentos vegetais fortificados; fator intrínseco no estômago é necessário para uma absorção ileal eficiente da ligação alimentar B12.</div><p>B12 is a cobalt-contendo vitamina essencial para a formação de glóbulos vermelhos, síntese de DNA, e saúde mielina/nervo via metabolismo de um carbono (parceria com folato). O fígado armazena anos de B12 para muitas pessoas – então a deficiência pode ser lenta e furtiva, então neurológica.</p><p>A stewardship do sangue e do nervo é o cuidado do corpo-como-templo. Os comedores somente de plantas precisam de alimentos ou suplementos fortificados confiáveis; idosos e aqueles com doença de absorção precisam de laboratórios e, às vezes, injeções — comprimidos<strong>nem sempre corrigir anemia perniciosa sem um plano.</strong></p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Carne, aves, peixes,now-how e produtos lácteos</li><li>Leveduras nutricionais fortificadas, leites vegetais e cereais de pequeno-almoço (verify label)</li><li>Alguns alimentos fermentados reivindicam análogos B12 —<strong>X não dependem de mitos tempeh/algas não verificados</strong>; use alimentos fortificados ou suplementos se vegan</li><li>Clams e fígado são especialmente ricos tradicionalmente</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais / históricas</h3><ul><li>A anemia perniciosa precedeu o isolamento do B12; dietas hepáticas e injeções posteriores transformaram os resultados.</li><li>Dietas tradicionais onívoras e laticínios-inclusivas forneceram B12 sem saber.</li><li>Nenhum “B12” bíblico; as leis alimentares limpas/limpas são categorias teológicas, não ensaios de cobalamina.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>Papel claro na prevenção/tratamento de anemia por deficiência de B12 e complicações neurológicas quando a deficiência é real.</li><li>Pesquisa sobre envelhecimento cognitivo, homocisteína e nutrição vegana reforça o monitoramento. Os problemas de absorção</li><li>(anemia perniciosa, gastrite, cirurgia bariátrica, metformina conversas de uso a longo prazo) são tão importantes como a dieta.</li><li>O soro B12, o ácido metilmalônico e os sinais clínicos orientam o cuidado—interprete com os profissionais.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>Deficiência pode causar fadiga, glossite, parestesias, problemas de equilíbrio e alterações cognitivas -<strong>avaliação urgente para sintomas neurológicos.</strong></li><li>O ácido fólico alto pode mascarar anemia enquanto o dano neurológico progride – avaliação equilibrada necessária.</li><li>O excesso de B12 de suplementos é geralmente excretado em pessoas com manipulação renal intacta; erupções cutâneas tipo acne notificadas anedotalmente com doses elevadas em algumas pessoas. As injeções de</li><li>são procedimentos médicos; auto-injetar apenas se prescrito e treinado.</li><li>O abuso de óxido nitroso pode precipitar lesão neurológica aguda relacionada ao B12 — educação médica de emergência, não ponta de bem-estar.</li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>Comprimidos orais de cianocobalamina (estável, comum)</li><li>Metilcobalamina (popular em alguns mercados)</li><li>Lozenges sublinguais (comercialização excede a magia única para muitas pessoas – absorção ainda parcialmente engolida)</li><li>Gelos e prescrições nasais</li><li>Hidroxocobalamina intramuscular/cianocobalamina por clínico</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagem (não são prescrições)</h3><p>-<strong>Estilo IDR para adultos:</strong>cerca de<strong>2,4 mcg/dia</strong>; mais altos nas tabelas de gravidez/lactação.</p><ul><li>Manutenção vegana suplementar muitas vezes usa<strong>mcg maior rotulado</strong>(por exemplo, centenas de mcg) porque a absorção do cristalino B12 é parcial - siga protocolos vegan dietitian/clinician.</li><li>Tratamento de deficiência usa<strong>muito maior</strong>regimes orais ou injetáveis<strong>**medicamente supervisionado</strong>.</li><li>Adultos idosos: muitas diretrizes incentivam alimentos fortificadosňveis ou suplementos porque o declínio do ácido/IF estomacal é comum – individualizar com laboratórios.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["vitamin-c-ascorbic-acid"] = { title: "Vitamina C (Ácido Ascórbico)", html: "<p class=\"entry-sub\">Vitamina antioxidante formadora de colagénios — clássico escorbuto-preventor que ainda prospera em placas de produção</p><div class=\"field\"><strong>Nome/formas comuns:</strong> Vitamina C; ácido ascórbico; ascorbatos minerais (ascorbato de sódio/cálcio); libertação cronometrada; formas de comercialização lipossomais; produtos do tipo éster-C. Abundante em muitas frutas e vegetais.</div><p>Vitamina C é uma vitamina essencial solúvel em água que os seres humanos não conseguem sintetizar. É necessário para ligação cruzada de colágeno (daí as gengivas sangrando do escorbuto e má cicatrização da ferida quando ausente), aumenta a absorção de ferro não-heme, e participa em redes de reciclagem antioxidante. O excesso é geralmente urinado para fora - até tolerância intestinal ou oxalato / pedra preocupações aparecem em altas cargas suplementares.</p><p>Citrus, quadris de rosas, pimentões e verdes folhosos exibem a farmácia colorida de alimentos do Criador. Os marinheiros aprenderam o escorbuto da maneira mais difícil; honramos essa história comendo frutas – não reivindicando curas gram-dose para cada estação viral.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Frutos de citrinos, kiwi destroços, morangos, goiaba</li><li>Pimentos de sino, brócolos, brotos de Bruxelas, tomates</li><li>Batatas (modestos, mas historicamente significativas)</li><li>Cantalupe e mamão</li><li>Frescos, melhores do que cozidos de longa data, para preservar a vitamina C</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais/históricas</h3><ul><li>Escorbuto em longas viagens em forma de história naval; citrinos e outros FEIOS frescos foram protetores muito antes do ácido ascórbico ser cristalizado.</li><li>O uso popular de quadris de rosa, chás de pinho e acerola pertence à tradição de plantas ricas em vitamina C.</li><li>Os frutos bíblicos (pomegranatos, uvas, etc.) contribuem de forma variada; não invente uma citação de “ácido ascórbico Levítico”.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna</h3><ul><li>Prevenir/tratar escorbuto é inequívoco quando existe deficiência.</li><li>Pesquisas com frio comum sugerem possíveis efeitos modestos sobre a duração em alguns usuários regulares —<strong>não</strong>prevenção confiável para a população em geral em megadoses, e não um substituto para vacinação ou repouso / cuidados médicos quando necessário.</li><li>IV alta dose de vitamina C é um tópico de pesquisa médica separado -<strong>não</strong>um protocolo DIY.</li><li>Melhoramento da absorção de ferro com refeições é a educação nutricional prática.</li><li>Ensaios de suplemento antioxidante em populações mistas têm sido complexos — fontes de alimentos continuam sendo o padrão mais seguro.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>Frank de Frank escorbuto é incomum em dietas variadas, mas acceleratorр em insegurança alimentar grave, alcoolismo, ou comida altamente restrita - precisa de cuidados médicos.</li><li>Doses orais elevadas causam diarreia, náuseasBRA e cólicas (tolerância de bolhas).</li><li>As conversas de risco de pedras nos rins se intensificam para algumas pessoas (oxalato) em altas doses de suplementos – personalize.</li><li>Deficiência de G6PD: doses IV muito elevadas têm risco de hemólise na literatura médica – contexto clínico.</li><li>Os ácidos mastigáveis podem corroer o esmalte do dente — boca rente.</li><li>A interrupção CEP após laminados de megadoses prolongadas tem raras anedotas de escorbuto de rebote — conforme aconselhado, se relevante.</li></ul><p>-<strong>Não substitui o tratamento do cancro</strong>ou antibióticos.</p></section><section class=\"entry-section\"><h3>Formas complementares</h3><ul><li>Comprimidos/pós de ácido ascórbico</li><li>Ascorbatos tamponados para estômagos sensíveis</li><li>Multi Multivitaminas com 45-90+ mg</li><li>Megadoses emergentes de “pacote”—ver carga diária total e açúcar</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagemm (não são prescrições)</h3><p>-<strong>Adulto RDA-estilo:</strong>sobre<strong>75 mg/dia</strong>para muitas mulheres e<strong>90 mg/dia</strong>para muitos homens;**+35 mg XXBX para fumantes em tabelas dos EUA.</p><ul><li>Gravidez/lactação RDAs estão mais elevadas - use tabelas pré-natais.</li><li>UL adulto comumente discutido perto<strong>2,000 mg/dia</strong>de suplementos; muitas pessoas fazem bem longe de alimentos.</li><li>Food-first facilmente encontra RDA para a maioria dos que comem produtos diários.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["vitamin-d"] = { title: "Vitamina D", html: "<p class=\"entry-sub\">Sunshine sterol hormone-precursor – parceiro de absorção de cálcio para o osso, com pesquisa de receptores mais ampla em andamento</p><div class=\"field\"><strong>Nome / formas comuns:</strong> Vitamina D2 (ergocalciferol) e vitamina D3 (colecalciferol). Vem da síntese cutânea exposta ao sol, peixes gordos, gemas de ovo, leite/leites/cereais fortificados e suplementos (cápsulas, gotas, receitas). 25-hidroxivitamina D Os exames de sangue orientam as conversas sobre o estado clínico.</div><p>Vitamina D é ativada no fígado e no rim para uma forma hormonal que regula o equilíbrio de cálcio e fosfato e mineralização óssea. Muitos tecidos têm receptores de vitamina D – pesquisa explora imune e outros papéis, mas a fisiologia óssea/mineral<strong>continua a ser o núcleo educacional mais claro.</strong>Status depende da latitude, cobertura cutânea, estação, idade, composição corporal e ingestão.</p><p>Luz e estações são presentes encomendados por Deus. Sabedoria inclui tempo ao ar livre, quando apropriado, cuidado com câncer de pele sensível, alimentos fortificados, e repleção guiada por laboratório – não garrafa não testada perseguindo ou bronzeamento-cama teologia.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Leites lácteos e vegetais reforçados</li><li>Gordura de peixe (salmão, sardinha, cavala)</li><li>Gemas de ovo</li><li>Cereais fortificados e alguns cogumelos (cogumelos tratados com UV podem fornecer D2)</li><li>Óleo de fígado de bacalhau (também vitaminas A &amp; D – não dupla megadose cegamente)</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais / históricas</h3><ul><li>Riquetes em cidades industrializadas com trabalho infantil indoor e poluição moldada ciência precoce de vitamina D; óleo de fígado de bacalhau e posterior fortificação mudou a saúde óssea pediátrica.</li><li>Luz solar como folclore medicina é antiga; o conhecimento de risco de câncer de pele é equilíbrio moderno.</li><li>Nenhum versículo diz “tomar 2,000 IU”; o sol de justiça de Malaquias é teológico, não um gráfico de dosagem.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>Prevenir/tratar a deficiência de vitamina D osteomalácia/raquitismo é fundamental.</li><li>Cuidados com queda/fratura e osteoporose integram vitamina D com cálcio, proteína e força – sob diretrizes clínicas.</li><li>Estudos de associação imune, humor e doença crônica são numerosos; o nexo causal e as metas ideais permanecem debatidos além de corrigir uma deficiência clara.</li><li>Os regimes intermitentes da Megadose existem em clínicas —<strong>não</strong>protocolos casuais do Instagram.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>Risco de deficiência: sol limitado, pele mais escura em altas latitudes, cobertura exclusiva, má absorção, obesidade, idosos, alguns medicamentos – teste quando indicado.</li></ul><p>-<strong>Toxicidade</strong>é quase sempre de suplementos excessivos, não sol: alto cálcio no sangue/urina, lesão renal, confusão – sérios problemas médicos.</p><ul><li>Pessoas com doença granulomatosa ou alguns linfomas podem ativar demais a vitamina D — cuidados especializados.</li><li>As tiazidas, digoxina e altas doses de cálcio precisam de coordenação ao complementar.</li><li>Gravidez: siga as orientações do laboratório obstétrico; evite megadoses a menos que prescrito.</li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>D3 softgels e gotas (comum)</li><li>D2 prescrições historicamente para alguns protocolos de deficiência</li><li>Combinações cálcio+D</li><li>Multivitaminas com 400–1,000 IU faixas típicas</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagemm (não são prescrições)</h3><p>-<strong>Estilo IDR para adultos (EUA):</strong>cerca de<strong>600 UI (15 mcg)/dia</strong>para muitos adultos até os 70 anos; cerca de<strong>800 UI (20 mcg)/dia</strong>para 71+.</p><ul><li>Muitos clínicos individualizam usando os laboratórios<strong>25(OH)D</strong>; a manutenção suplementar muitas vezes cai em centenas para baixo milhares de UI— o laboratório<strong>e o clínico batem alvos genéricos.</strong></li><li>Adulto UL comumente discutido perto<strong>4,000 IU/dia</strong>, a menos que um clínico direciona maior repleção de curto prazo.</li><li>A exposição solar não é uma “dose” precisa e deve equilibrar o risco de queimadura/cancro.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["vitamin-e"] = { title: "Vitamina E", html: "<p class=\"entry-sub\">Antioxidante lipossolúvel de membranas — protege gorduras poliinsaturadas em células (primeiro alimento; precaução megadose)</p><div class=\"field\"><strong>Nome / formas comuns:</strong> Vitamina E – família de tocoferóis e tocotrienóis; suplementos dietéticos e mais rotulados focam em<strong>alfa-tocoferol</strong>. As formas incluem RRR-alfa-tocoferol natural (às vezes rotulado d-alfa) e sintético all-rac (dl-alfa) com diferentes biopotências; produtos de tocoferol mistos também vendidos.</div><p>Vitamina E ajuda a proteger as membranas celulares contra danos oxidativos, trabalhando com outros sistemas antioxidantes. Viaja com gordura e lipoproteínas. A deficiência de Frank é rara, exceto em doenças de má absorção de gordura ou transporte genético – ainda assim, o alfa-tocoferol de alta dose suplementar tem sido estudado extensivamente com sinais de segurança mistos<strong>em altas doses.</strong></p><p>Óleos de sementes, nozes e verduras carregam este presente em matrizes alimentares. A aeromoça prefere padrões alimentares em vez de heroísmos antioxidantes em doses elevadas, especialmente ao lado de anticoagulantes.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Nozes e sementes (almonds, avelãs, sementes de girassol)</li><li>Óleos vegetais (óleo de girassol, cártamo, óleo de germe de trigo)</li><li>Manteiga de amendoim</li><li>Espinafre e outros greens</li><li>Abacate</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais / históricas</h3><ul><li>Isolado em ciência nutricional no início do século XX através de pesquisa de fertilidade animal (nomeação histórica)—aplicações humanas refinados posteriormente.</li><li>Comer nozes e sementes tradicionais fornecidos tocoferóis sem cápsulas.</li><li>Mantenha o enquadramento bíblico para o fornecimento geral de sementes/plantas oleosas – sem texto forçado à prova de tocoferol.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>Corrigir a verdadeira deficiência (por exemplo, em abetalipoproteinemia ou colestase grave) é nutrição médica.</li><li>Grandes ensaios de prevenção de uma dose elevada de vitamina E suplementar para doenças cardíacas ou cancro têm sido muitas vezes decepcionantes; alguns aumentos de hemorragia ou outras preocupações de risco com doses elevadas em determinados grupos.</li><li>A vitamina E tópica para cicatrizes tem conversas de pessoas mistas vs. evidência - teste de patch; oral .</li><li>Os tocoferóis mistos/tocotrienóis são ativos na pesquisa; o marketing muitas vezes à frente do consenso.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>Deficiência: lesão nervosa, fraqueza muscular, problemas imunológicos em ambientes clínicos raros — necessita de especialistas.</li></ul><p>-<strong>Suplementos de dose elevada</strong>podem aumentar o risco de hemorragia (especialmente com varfarina, antiagregantes plaquetários ou antes da cirurgia)— coordenação clínica<strong>; nunca anticoagulantes autoparados.</strong></p><ul><li>Náuseas ou diarreia possível com grandes doses.</li><li>Fumantes e história de betacaroteno de alta dose nos lembram que megadoses antioxidantes não são universalmente seguras — a vitamina E tem sua própria literatura de cuidados com dose. Gravidez</li><li>: permanecer perto dos níveis pré-natais, salvo indicação em contrário.</li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>Softgels de alfa-tocoferol (IU ou rotulagem de mg — leia atentamente a conversão)</li><li>Mistura de tocoferol</li><li>Multivitaminas com modestas quantidades de RDA</li><li>Óleo de germe de trigo como fonte alimentar</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagem (não são prescrições)</h3><p>-<strong>Adulto RDA-estilo:</strong>sobre<strong>15 mg/dia alfa-tocoferol</strong>.</p><ul><li>O UL adulto comumente discutido fica perto de<strong>1.000 mg/dia</strong>(cerca de<strong>1.500 UI naturais</strong>ou<strong>1.100 UI sintéticas</strong>) de suplementos —<strong>muitos educadores desencorajam o uso rotineiro em altas doses</strong>sem indicação por causa de sinais de sangramento e de ensaios.</li><li>Fontes alimentares geralmente cobrem as necessidades de pessoas comendo nozes/sementes/óleos.</li><li>UI-to-mg conversões diferem para natural vs. sintético – siga as regras atuais da etiqueta e matemática clínica.</li></ul></section>" };
window.VITAMIN_LOCALES["pt"]["zinc"] = { title: "Zinco", html: "<p class=\"entry-sub\">Immune-enzyme &amp; gust/smell mineral — cofactor de cicatrização de feridas que pune tanto a escassez como o excesso</p><div class=\"field\"><strong>Nome / formas comuns:</strong> Zinco (mineral essencial). Os sais adicionais incluem gluconato de zinco, acetato, citrato, picolinato, sulfato e óxido; também conservas de zinco para folclore de época fria e óxido de zinco tópico (protetor de pele – uso diferente).</div><p>Zinc é um cofactor catalítico e estrutural em centenas de proteínas, incluindo factores de transcrição de zinco-dedo de ligação ao ADN, função celular imune e enzimas de reparação de feridas. O corpo tem armazenamento de zinco limitado; a ingestão deve ser regular. O excesso de zinco induz deficiência de cobre e outros danos – equilíbrio é a lição.</p><p>Minerais da terra estação nossas enzimas. Stewardship significa ostras e carne para alguns, feijão e sementes com preparação inteligente para outros, e recusando intermináveis mega-lozenges que silenciam cobre e revestimento do estômago.</p><section class=\"entry-section\"><h3>Fontes alimentares</h3><ul><li>Oysters (notoriamente ricos), caranguejo, lagosta</li><li>Beef, porco, aves escuras</li><li>Sementes de abóbora, sementes de cânhamo, caju</li><li>Legume e grãos integrais (filtatos reduzem a absorção – absorvendo/ fermentando/fome ajuda educacionalmente)</li><li>Cereais fortificados</li><li>Dairy contribui com alguns zinco</li></ul></section><section class=\"entry-section\"><h3>Notas tradicionais / históricas</h3><ul><li>As síndromes de deficiência de zinco/hipogonadismo foram caracterizadas em estudos de nutrição do Oriente Médio do século XX com dietas ricas em fitato sem fermento – histórico de nutrição clínica.</li><li>Calamina e óxido de zinco tradições de pele são mais antigos artesanato farmácia.</li><li>Referências bíblicas à mineração e metais (por exemplo, as riquezas da terra de Deuteronômio) não são gráficos RDA de zinco — manter a humildade.</li></ul></section><section class=\"entry-section\"><h3>Temas de pesquisa moderna (qualitativos)</h3><ul><li>Prevenir/tratar deficiência (incluindo alguns protocolos de saúde pública diarréia-doença em crianças em regiões específicas) é evidência-ancorado<strong>nesses contextos clínicos/públicos-saúde</strong>—não é um DIY universal para cada problema de estômago em casa sem orientação.</li><li>A pesquisa de lozenge de época fria é mista; timing, forma de sal (gluconato/acetato frequentemente estudado), e evitar danos olfativos de zinco intranasal são pontos-chave de ensino.</li><li>Degeneração macular relacionada à idade As fórmulas do tipo AREDS usam zinco<strong>em protocolos específicos de olhos médicos</strong>— não improvisam o tratamento da doença ocular.</li><li>O marketing immune “boost” excede a imunologia nuanceada.</li></ul></section><section class=\"entry-section\"><h3>Precauções por deficiência / excesso</h3><ul><li>Deficiência: mau gosto / cheiro, má cicatrização de feridas, desbaste de cabelo, diarréia, vulnerabilidade imunológica - diagnose corretamente.</li></ul><p>-<strong>Excesso:</strong>náusea, vômitos, dor abdominal; ingestão elevada crônica → deficiência de cobre, anemia, problemas neurológicos.</p><ul><li>O zinco intranasal ligado historicamente a<strong>perda permanente de olfato</strong>—<strong>não utiliza pulverizadores/geles de nariz zinco.</strong>Lozenges</li><li>pode irritar a boca e o estômago; siga os limites da embalagem.</li><li>Antibióticos (quinolonas, tetraciclinas) e interações penicilamina—tempo separado; aconselhamento farmacêutico.</li><li>Retirar de mega-refeições de alto grau ou megadoses de ferro se a absorção é o objetivo clínico – individualizar.</li></ul></section><section class=\"entry-section\"><h3>Formas suplementares típicas</h3><ul><li>Gluconato de zinco / citrato / picolinato cápsulas</li><li>Lozenges frios (acetato/gluconato)</li><li>Multivitaminas com ~8–15 mg</li><li>Óxido de zinco tópico fralda/protectores de pele (externos)</li><li>Misturas derivadas de Oyster – precaução alérgica</li></ul></section><section class=\"entry-section\"><h3>Faixas educativas de dosagem (não são prescrições)</h3><p>-<strong>Estilo IDR para adultos:</strong>cerca de<strong>8 mg/dia</strong>para muitas mulheres e<strong>11 mg/dia</strong>para muitos homens; mais altos nas tabelas de gravidez/lactação.</p><ul><li>Adulto UL comumente discutido perto<strong>40 mg/dia</strong>zinco elementar de todas as fontes - fácil de exceder com pastilhas empilhadas + multi + alimentos fortificados.</li><li>Protocolos curtos de lozenge de temporada fria em rótulos ainda requerem ficar sob irritação e sabedoria da UL; parar se náuseas ou feridas na boca.</li><li>Planejadores vegetarianos podem precisar de um pouco mais de zinco dietético ou suplementação cuidadosa por causa de fitato – dietitian útil.</li></ul></section>" };

(function () {
  var originals = Object.create(null);
  var captured = false;

  function captureEnFromDom() {
    if (captured) return;
    document.querySelectorAll("details.ref-entry").forEach(function (el) {
      var summary = el.querySelector(":scope > summary");
      var body = el.querySelector(":scope > .entry-body");
      if (!summary || !body) return;
      originals[el.id] = { title: summary.textContent, html: body.innerHTML };
    });
    captured = true;
  }

  window.bpApplyVitaminLocales = function bpApplyVitaminLocales() {
    var map = window.VITAMIN_LOCALES;
    if (!map) return;
    captureEnFromDom();
    var lang = window.bpLang || "en";
    document.querySelectorAll("details.ref-entry").forEach(function (el) {
      var id = el.id;
      var summary = el.querySelector(":scope > summary");
      var body = el.querySelector(":scope > .entry-body");
      if (!summary || !body) return;
      var entry = null;
      if (lang === "en") {
        entry = (map.en && map.en[id]) || originals[id];
      } else if (map[lang]) {
        entry = map[lang][id];
      }
      if (!entry) return;
      summary.textContent = entry.title;
      body.innerHTML = entry.html;
    });
    document.querySelectorAll(".ref-toc a[href^='#']").forEach(function (a) {
      var id = a.getAttribute("href").slice(1);
      var entry = null;
      if (lang === "en") entry = (map.en && map.en[id]) || originals[id];
      else if (map[lang]) entry = map[lang][id];
      if (entry && entry.title) a.textContent = entry.title;
    });
  };

  var prev = window.bpApplyPageI18n;
  window.bpApplyPageI18n = function () {
    if (typeof prev === "function") prev();
    window.bpApplyVitaminLocales();
  };
})();
